            requires equal(self.id(), old(perm).view().patomic),
            ensures
                equal(old(perm).view().value, ret),
                final(perm).view().patomic == old(perm).view().patomic,
                final(perm).view().value as int == $modname::wrapping_sub(old(perm).view().value, n),
