        Self::Left(left)
    }

    pub proof fn tracked_new_right(tracked right: R) -> (tracked res: Self)
        returns
            Self::Right(right),
    {
        Self::Right(right)
    }

    pub proof fn tracked_take_left(tracked self) -> (tracked res: L)
        requires
            self is Left,
        returns
            self->Left_0,
    {
        match self {
            Self::Left(left) => left,
            Self::Right(_) => proof_from_false(),
        }
